// 观辰 P8-4 (2026-10-24): Simplified -> Traditional Chinese (Taiwan standard), same chain as OpenCC "s2twp".
// Stage 1: 观辰 overrides + OpenCC phrases (longest match), otherwise one character at a time.
// Stage 2: Taiwan phrases, then Taiwan variant phrases, then Taiwan variant characters (first dictionary that matches wins).
// The table (zh-tw-data.json) is generated by tools/gen_zh_tw.py from the OpenCC dictionaries (Apache-2.0).
const has = (o, k) => Object.prototype.hasOwnProperty.call(o, k);   // also works in Safari before 15.4
export function makeConverter(data) {
  const maxLen = o => Object.keys(o).reduce((m, k) => Math.max(m, k.length), 1);
  const P = data.p, C = data.c, PL = maxLen(P), TW = data.tw.map(d => [d, maxLen(d)]);
  function stage1(s) {
    let out = '';
    for (let i = 0; i < s.length;) {
      let hit = false;
      for (let L = Math.min(PL, s.length - i); L >= 2; L--) { const w = s.substr(i, L); if (has(P, w)) { out += P[w]; i += L; hit = true; break; } }
      if (!hit) { const ch = s[i]; out += has(C, ch) ? C[ch] : ch; i++; }
    }
    return out;
  }
  function stage2(s) {
    let out = '';
    for (let i = 0; i < s.length;) {
      let hit = false;
      for (const [d, ml] of TW) {
        for (let L = Math.min(ml, s.length - i); L >= 1; L--) { const w = s.substr(i, L); if (has(d, w)) { out += d[w]; i += L; hit = true; break; } }
        if (hit) break;
      }
      if (!hit) { out += s[i]; i++; }
    }
    return out;
  }
  const CJK = /[㐀-鿿]/;
  return s => (typeof s === 'string' && CJK.test(s) ? stage2(stage1(s)) : s);
}
